import React from 'react';

function Julie({ stone }) {

  if (!stone || stone.length === 0) {
    return <p>No data available</p>;
  }

  return (
    <div>
      {stone.map((value) => (

        <div key={value.id} className="mat">
          <video
            width="560"
            height="315"
            controls
            autoPlay
            muted
            src={value.video}
            title={value.name}
          >
            Your browser does not support the video tag.
          </video>

          <br /><br />
          <h2>{value.name}</h2>
          <h3>Type: {value.type}</h3>
          <p>{value.description}</p>
          <h4>Rating: {value.rating}</h4>
        </div>
      ))}
    </div>
  );
}

export default Julie;
